import type { FeedbackTrigger } from '~/client';
import type { FeedbackBadgeEntry } from './types';

// Key order defines the user-visible filter order.
export const feedbackTriggerConfig: Record<FeedbackTrigger, FeedbackBadgeEntry> = {
  workshift_end: { label: 'Workshift End', variant: 'default' },
  scheduled_review: { label: 'Scheduled Review', variant: 'info' },
  critical_threshold: { label: 'Critical Threshold', variant: 'destructive' },
};

const defaultFeedbackTrigger: FeedbackBadgeEntry = { label: '', variant: 'default' };

export function getFeedbackTriggerBadge(trigger: FeedbackTrigger): FeedbackBadgeEntry {
  return feedbackTriggerConfig[trigger] ?? { ...defaultFeedbackTrigger, label: snakeCaseToCapitalizedCase(trigger) };
}

export const coachingFeedbackTriggers: SelectItem<FeedbackTrigger>[] = Object.entries(feedbackTriggerConfig).map(
  ([value, { label }]) => ({ value: value as FeedbackTrigger, name: label })
);
