import type { FeedbackType } from '~/client';
import type { FeedbackBadgeEntry } from './types';

// Key order defines the user-visible filter order.
export const feedbackTypeConfig: Record<FeedbackType, FeedbackBadgeEntry> = {
  cheering: { label: 'Cheering', variant: 'success' },
  coaching: { label: 'Coaching', variant: 'default' },
  warning: { label: 'Warning', variant: 'warning' },
  trend_report: { label: 'Trend Report', variant: 'info' },
};

const defaultFeedbackType: FeedbackBadgeEntry = { label: '', variant: 'default' };

export function getFeedbackTypeBadge(type: FeedbackType): FeedbackBadgeEntry {
  return feedbackTypeConfig[type] ?? { ...defaultFeedbackType, label: snakeCaseToCapitalizedCase(type) };
}

export const coachingFeedbackTypes: SelectItem<FeedbackType>[] = Object.entries(feedbackTypeConfig).map(
  ([value, { label }]) => ({ value: value as FeedbackType, name: label })
);
